from .core import (CONTENT, SITE, UPDATED, breadcrumb, build_challenge, faq, learning_schema, lesson_header, page, quick_answer, takeaways)


def build():
    slug='agent-loop';d=CONTENT['lessons'][slug]
    agent_body=f'''<div class="container">{lesson_header(slug,'⌘')}{quick_answer(d['quick'])}<div class="lesson-grid"><div><section class="card interactive"><div class="panel-title"><span>Live simulation</span><span class="badge">Step through manually</span></div><div class="task-box" style="margin-top:13px"><strong>Task</strong><br>Find the weather in Tokyo and tell me if I need an umbrella.</div><div class="agent-main"><div><div class="agent-flow"><div class="agent-node active" data-agent-node>User</div><span class="flow-arrow">→</span><div class="agent-node" data-agent-node>Agent</div><span class="flow-arrow">→</span><div class="agent-node" data-agent-node>Tool</div><span class="flow-arrow">→</span><div class="agent-node" data-agent-node>Observe</div><span class="flow-arrow">→</span><div class="agent-node" data-agent-node>Refine</div><span class="flow-arrow">→</span><div class="agent-node" data-agent-node>Answer</div></div><div class="note"><strong>Current state:</strong> <span data-agent-status>The agent reads the user task and identifies missing information.</span></div><div class="selected-panel"><span class="subtle">Final answer</span><div data-agent-result style="font-weight:820;margin-top:4px">Waiting for final answer…</div></div></div><aside><strong style="font-size:13px">Execution timeline</strong><ol class="timeline"><li class="active" data-time-step>Understand task</li><li data-time-step>Choose action</li><li data-time-step>Call weather tool</li><li data-time-step>Observe result</li><li data-time-step>Retry or refine</li><li data-time-step>Final answer</li></ol><div class="tool-result"><strong>Tool result</strong><div class="subtle" style="margin-top:6px">Tokyo · Light Rain · 18°C<br>Humidity 92% · Wind NE 12 km/h</div></div><div class="metrics"><div class="metric">Latency<br><strong>1.1s</strong></div><div class="metric">Est. cost<br><strong>$0.0007</strong></div></div></aside></div><div class="agent-controls" style="grid-template-columns:1fr 1fr 1fr;margin-top:15px"><button type="button" class="btn primary" data-agent-next>Next step →</button><button type="button" class="btn" data-agent-reset>Reset</button><button type="button" class="btn danger" data-agent-error>Simulate tool error</button></div></section>{takeaways([('Agents operate in loops','A result becomes input to the next decision.'),('Tools extend capability','Actions connect the model to external systems.'),('Observations guide decisions','Tool output changes what the agent does next.'),('Reliability needs recovery','Retries and termination rules belong in the design.')])}{build_challenge('Add a termination rule and fallback','Define when the agent should retry, when it should stop, and what it should tell the user when the weather tool stays unavailable.')}</div><aside class="lesson-sidebar"><div class="card side-card"><h3>What you’ll learn</h3><ul class="check-list"><li>How agent loops differ from chat</li><li>Where tool calls fit</li><li>Why observations and retries matter</li></ul></div><div class="card side-card"><h3>Control the loop</h3><p class="subtle">Use the simulator controls to advance one step at a time, reset state, or inject a failure.</p></div></aside></div><section class="card section-explainer"><span class="eyebrow">Concept guide</span><h2>What is an AI agent loop?</h2><p>An agent loop is an iterative control process in which a model or agent interprets the current state, chooses an action, receives an observation, and decides whether to continue or return a final answer.</p><h3>Why do agents use tools?</h3><p>Tools allow an agent to access information or perform actions that are not contained in the model itself, such as querying a database, calling an API, running code, or updating another system.</p><h3>What is an observation?</h3><p>An observation is the result returned from an action or tool. The agent uses that result as new evidence for the next decision.</p><h3>What makes an agent reliable?</h3><p>Production agents need explicit tool contracts, validation, retries, timeouts, authorization boundaries, observability, and termination conditions. The loop alone is not the reliability layer.</p><h3>Common questions</h3>{faq([('Is every chatbot an agent?','No. A chatbot can answer directly without taking iterative actions through tools.'),('Does an agent need hidden chain-of-thought?','No. Agent control can be implemented through explicit state, tool calls, structured decisions, and observable transitions.'),('Why simulate tool errors?','Because failures are normal in production; recovery behavior is part of the system design.'),('Is ReAct the only agent pattern?','No. Plan-and-execute, workflows, state machines, and other orchestration patterns are also common.')])}<div class="references"><strong>SeeAI learning note</strong> · Reviewed {UPDATED}. The weather values and timing are illustrative; the control-flow concepts are the learning target.</div></section><section class="card next-band"><div><strong>You completed the MVP learning path.</strong><div class="subtle">The next SeeAI labs will move into RAG, MCP, evaluation, and production systems.</div></div><a class="btn primary" href="/en/early-access/?intent=completed-path">Join Early Access →</a></section></div>'''
    (SITE/f'en/lessons/{slug}/index.html').write_text(page(f"{d['name']} — How AI agents use tools and observations | SeeAI",d['description'],f'/en/lessons/{slug}/',agent_body,active='Lessons',schemas=[learning_schema(slug),breadcrumb([('SeeAI','/en/'),('Lessons','/en/#lessons'),(d['name'],f'/en/lessons/{slug}/')])],scripts='<script src="/assets/agent.js" defer></script>'),encoding='utf-8')
